body:
Current setup: hermes gateway and dashboard are deployed separately but share the same HERMES_HOME. Since the dashboard runs with --insecure (no
  built-in auth), we front it with nginx + tinyauth in forward-auth mode for username/password + cookie validation. tinyauth and dashboard share one hostname, and nginx
  routes between them by path / Referer.

  Key nginx config (the proxy section):
```
  # Restore the real scheme (ALB terminates TLS, forwards as HTTP)
  map $http_x_forwarded_proto $real_scheme {
    default $scheme; https https; http http;
  }

  # /assets/ and /favicon.ico exist in both tinyauth and dashboard — split by Referer
  map $http_referer $shared_upstream {
    default                                                                                    "127.0.0.1:9119";
    "~*^https?://[^/]+/(login|logout|continue|unauthorized|forgot-password|totp|error)(\?|$|/)"  "127.0.0.1:3000";
  }

  server {
    listen 8080;

    proxy_set_header Host              $host;
    proxy_set_header X-Forwarded-Proto $real_scheme;

    # Narrow the cookie that tinyauth issues with Domain=.<YOUR_DOMAIN>
    # down to the single hostname, so other *.<YOUR_DOMAIN> services
    # can't see this session.
    proxy_cookie_domain <YOUR_DOMAIN>  dashboard.<YOUR_DOMAIN>;
    proxy_cookie_domain .<YOUR_DOMAIN> dashboard.<YOUR_DOMAIN>;

    # forward-auth subrequest
    location = /_tinyauth_check {
      internal;
      proxy_pass http://127.0.0.1:3000/api/auth/nginx;
      proxy_pass_request_body off;
      proxy_set_header Content-Length     "";
      proxy_set_header X-Forwarded-Host   $host;
      proxy_set_header X-Forwarded-Proto  $real_scheme;
      proxy_set_header X-Forwarded-URI    $request_uri;
      proxy_set_header X-Forwarded-Method $request_method;
    }

    # Unauthenticated → redirect to /login
    location @signin {
      return 302 $real_scheme://$host/login?redirect_uri=$real_scheme://$host$request_uri;
    }

    # tinyauth's own UI / API
    location ~ ^/(login|logout|continue|unauthorized|forgot-password)$ {
      proxy_pass http://127.0.0.1:3000;
    }
    location ~ ^/api/(login|logout|user|app|healthcheck|auth/|oauth/|totp/) {
      proxy_pass http://127.0.0.1:3000;
    }

    # Conflicting paths — split by Referer
    location /assets/       { proxy_pass http://$shared_upstream; }
    location = /favicon.ico { proxy_pass http://$shared_upstream; }

    # Everything else goes through forward-auth → dashboard
    location / {
      auth_request /_tinyauth_check;
      error_page 401 = @signin;

      proxy_pass http://127.0.0.1:9119;

      # WebSocket
      proxy_set_header Upgrade    $http_upgrade;
      proxy_set_header Connection "upgrade";
    }
  }
```
